import{_ as o}from"./chunks/image1.Bk1JI49V.js";import{_ as a}from"./chunks/image2.UYnXny4D.js";import{_ as e}from"./chunks/image3.z0vX6Nw7.js";import{_ as r}from"./chunks/image4.Co4Tm3RS.js";import{_ as p}from"./chunks/image5.NlMtFgFW.js";import{_ as i,c as l,o as n,ae as g}from"./chunks/framework.B8KKhRA6.js";const T=JSON.parse('{"title":"4-3. 육아시간 사용지침","description":"","frontmatter":{"title":"4-3. 육아시간 사용지침"},"headers":[],"relativePath":"manual/4-3._육아시간_사용지침.md","filePath":"manual/4-3._육아시간_사용지침.md"}'),s={name:"manual/4-3._육아시간_사용지침.md"};function h(c,t,u,_,d,q){return n(),l("div",null,t[0]||(t[0]=[g('<p>&quot;문화와 예술로 행복한 서울 만들기&quot;</p><p>+-------------------+--------------------------------------------------+ | &gt; 문서번호 | &gt; 인사팀-1080 | +:=================:+==================================================+ | &gt; 보존기간 | &gt; 준영구 | +-------------------+--------------------------------------------------+ | &gt; 결재일자 | &gt; 2024. 04. 01. | +-------------------+--------------------------------------------------+ | &gt; 공개여부 | &gt; 공개 | +-------------------+--------------------------------------------------+ | &gt; 방침번호 | &gt; 대표이사 방침 제(145)호 | +-------------------+--------------------------------------------------+</p><p>+---------------------------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+ | &gt; ★사원 | &gt; 팀장 | &gt; 본부장 | &gt; 대표이사 | :============================================================================================================:+ | &gt; <img src="'+o+'" alt="" width="0.42205161854768153in" height="0.125in"> | &gt; <img src="'+a+'" alt="" width="0.4095909886264217in" height="0.11666557305336833in"> | &gt; <img src="'+e+'" alt="" width="0.4229658792650919in" height="0.125in"> | &gt; <strong>04/01</strong> | | | | | &gt; | | | | | &gt; <img src="'+r+'" alt="" width="0.4065540244969379in" height="0.125in"> | +---------------------------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+ | &gt; 협 조 | | +---------------------------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+ | | +--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+</p><blockquote><p><strong>서울문화재단 육아시간 사용지침</strong></p></blockquote><p><img src="'+p+'" alt="" width="3.436900699912511in" height="0.5166666666666667in"></p><blockquote><p><strong>서울문화재단 육아시간 사용지침</strong></p><p><strong>「지방공무원 복무규정」및「서울특별시 공무원 복무조례」에 근거하여 서울문화재단 복무규정을 개정하였으며, 이에 따라 육아시간 사용과 관련한 세부 운영지침을 마련 하여 운영하고자 함</strong></p><p>※ &quot;육아시간&quot;이란 일‧가정의 양립 및 가족친화적인 근무환경 조성을 위하여</p><p>만 5세 이하의 자녀를 가진 직원에게 재단이 유급으로 제공하는 휴가시간을 말한다.</p></blockquote><h1 id="기본-개요" tabindex="-1">기본 개요 <a class="header-anchor" href="#기본-개요" aria-label="Permalink to &quot;기본 개요&quot;">​</a></h1><h2 id="□-추진-근거" tabindex="-1">□ 추진 근거 <a class="header-anchor" href="#□-추진-근거" aria-label="Permalink to &quot;□ 추진 근거&quot;">​</a></h2><blockquote><p>Ⅰ</p><p>ㅇ 서울문화재단 복무규정 제39조(육아시간)</p><p><strong>제39조(육아시간)</strong> 만 5세 이하의 자녀를 가진 직원은 24개월의 범위 내에서 자녀돌봄, 육아 등을 위한 1일 최대 2시간의 유급 육아시간을 받을 수 있으며 육아시간 운영에 필요한 사항은 대표이사가 따로 정한다. &lt;신설 2024. 2. 27.&gt;</p><p>ㅇ 서울특별시 공무원 복무 조례 제24조(특별휴가) 제4항</p><p><strong>제24조(특별휴가)</strong> ④ 5세 이하의 자녀를 가진 공무원은 24개월의 범위에서 자녀돌봄, 육아 등을 위한 1일 최대 2시간의 육아시간을 받을 수 있으며, 임신 중인 여성공무원은 1일 2 시간의 범위에서 휴식이나 병원 진료 등을 위한 모성권 보장시간을 받을 수 있다. &lt;개정 2019. 5. 16., 2019. 9. 26., 2023. 5. 22.&gt;</p></blockquote><h2 id="□-적용-범위" tabindex="-1">□ 적용 범위 <a class="header-anchor" href="#□-적용-범위" aria-label="Permalink to &quot;□ 적용 범위&quot;">​</a></h2><blockquote><p>ㅇ 적용 대상: 만 5세 이하(생후 72개월 미만)의 자녀(입양한 자녀 포함) 를 가진 직원</p><p>ㅇ 적용 기간: 자녀당 24개월의 범위에서 1일 2시간의 육아시간 사용 가능</p></blockquote><h1 id="육아시간-세부-운영지침" tabindex="-1">육아시간 세부 운영지침 <a class="header-anchor" href="#육아시간-세부-운영지침" aria-label="Permalink to &quot;육아시간 세부 운영지침&quot;">​</a></h1><blockquote><p>Ⅱ</p></blockquote><h2 id="육아시간-사용" tabindex="-1">육아시간 사용 <a class="header-anchor" href="#육아시간-사용" aria-label="Permalink to &quot;육아시간 사용&quot;">​</a></h2><blockquote><p>ㅇ 5세 이하(생후 72개월 미만)의 자녀를 가진 직원은 24개월의 범위에서 1일 2시간의 육아시간 사용 가능</p><p>ㅇ 사용신청은 일 단위로, 1일 2시간 범위 내에서 가능</p></blockquote><ul><li>사용한 날을 기준으로 1일을 공제하며, 2시간 미만의 시간을 사용하더라도 1일을 사용한 것으로 봄</li></ul><blockquote><p>ㅇ 24개월 산정기준: 20일마다 1개월 사용한 것으로 봄</p><p><strong>[예시]</strong> 직원 A가 육아시간을 &#39;24.4.1.~5.(5일), 4.15.~19.(5일), 5.7.~10.(4일), 5.20.~24.(5</p><p>일), 5.28.(1일)에 사용한 경우, 총 20일을 사용했으므로 1개월을 사용한 것으로 봄. 이후 연내에 육아시간을 사용하지 않았을 경우, &#39;25.1.1. 기준으로 산정한 A의 잔여 육아시간 이용가능 개월 수는 23개월(24개월-1개월)</p><p>ㅇ 자녀가 6세에 달한 날에 남아있는 육아시간은 소멸되며, 5세 이하의 자녀가 2명 이상인 경우에는 자녀 1인당 각각 사용할 수 있으나, 동일한 날에 중복하여 사용할 수 없음</p></blockquote><h2 id="사용-시-유의사항" tabindex="-1">사용 시 유의사항 <a class="header-anchor" href="#사용-시-유의사항" aria-label="Permalink to &quot;사용 시 유의사항&quot;">​</a></h2><blockquote><p>ㅇ 육아시간 사용일의 실근무시간은 4시간 이상이 되어야 하며, 최소 근무시간(4시간)을 충족하지 못한 육아시간 사용은 연차로 공제함</p><p><strong>[예시] 일 8시간 근무 기준</strong></p><p>∘ 육아시간 2시간, 연차 3시간 사용 시 → 연차 5시간 사용으로 공제</p><p>∘ 육아시간 2시간, 병가 4시간 사용 시 → 연차 2시간, 병가 4시간 사용으로 공제</p><p>ㅇ 육아시간 사용일이 포함된 주에는 탄력적 근로시간제 사용 불가 ㅇ 육아시간 사용일에는 근무시간 전‧후에 시간외근무 불가</p><p>ㅇ 육아시간은 근로시간 단축제(임신기, 육아기 등)와 중복 사용 불가</p><p>ㅇ 육아시간은 수유시간(복무규정 제38조)과 중복 사용 불가</p></blockquote><h1 id="시행원칙-및-신청절차" tabindex="-1">시행원칙 및 신청절차 <a class="header-anchor" href="#시행원칙-및-신청절차" aria-label="Permalink to &quot;시행원칙 및 신청절차&quot;">​</a></h1><h2 id="시행원칙" tabindex="-1">시행원칙 <a class="header-anchor" href="#시행원칙" aria-label="Permalink to &quot;시행원칙&quot;">​</a></h2><blockquote><p>Ⅳ</p><p>ㅇ 인력운영 상황, 대민 서비스 제공 및 공무수행 필요성 등을 종합적으로 고려하여 승인함</p><p>ㅇ 부서장은 부서의 인력운영 상황, 민원업무 처리 등 공무수행에 지장이 없는 범위에서 육아시간을 사용할 수 있도록 적극적으로 보장하여야 함</p></blockquote><h2 id="신청절차" tabindex="-1">신청절차 <a class="header-anchor" href="#신청절차" aria-label="Permalink to &quot;신청절차&quot;">​</a></h2><p>+----------------+------------------+------------------------------------------------+ | &gt; 구분 | 기한 | 내용 | +================+==================+================================================+ | &gt; 최초 사용 시 | 사용 시점 3일 전 | &gt; - 복무 담당자에게 육아시간 신청 협조문 송부 | | | | &gt; | | | | &gt; ※ 결재라인 : 부서장(전결) | | | | &gt; | | | | &gt; ※ 신청서(양식 1) 및 증빙서류 첨부 | | | | &gt; | | | | &gt; (병원의 출생증명서 또는 주민등록등본) | | +------------------+------------------------------------------------+ | | 사용 시점 전 | &gt; - 더존iU&gt;근무상황부&gt;상신 | | | | &gt; | | | | &gt; ※ 결재라인 : 부서장(전결) | +----------------+------------------+------------------------------------------------+ | &gt; 이후 사용 시 | 사용 시점 전 | &gt; - 더존iU&gt;근무상황부&gt;상신 | | | | &gt; | | | | &gt; ※ 결재라인 : 부서장(전결) | +----------------+------------------+------------------------------------------------+</p><blockquote><p>ㅇ 근무시간 중의 적절한 시간을 선택하여 신청할 수 있으며, 승인대상 여부는 [병원의 출생증명서 또는 주민등록등본]{.underline}으로 확인(최초 이용 시에 한하여 제출)</p><p>ㅇ 근무상황부 상신 방법</p></blockquote><ul><li><p>기간: 일 단위</p></li><li><p>시간: 1일 2시간 이내 (분할사용 불가)</p></li><li><p>자녀가 2명 이상인 경우, 신청사유에 해당 자녀의 이름 기재하여야 함</p></li><li><p>신청 내용이 변경될 경우, 기존 신청내역 삭제 후 변경된 내용으로 다시 결재받아야 함</p></li></ul><h2 id="적용례" tabindex="-1">적용례 <a class="header-anchor" href="#적용례" aria-label="Permalink to &quot;적용례&quot;">​</a></h2><blockquote><p>ㅇ 이 지침은 대표이사 승인 득한 날로부터 시행한다</p><p>붙임문서 1. 육아시간 신청서(양식) 1부.</p></blockquote><ol start="2"><li><p><strong>서울문화재단 복무규정 1부.</strong></p></li><li><p><strong>서울특별시 공무원 복무 조례 1부. 끝.</strong></p></li></ol>',29)]))}const w=i(s,[["render",h]]);export{T as __pageData,w as default};
